const output = resolve(outputPath);
const backup = resolve(dirname(output), 'backups/source.json');
const source = await readFile(inputPath);
let config;
try {
  config = JSON.parse(source.toString('utf8'));
} catch (error) {
  if (!(error instanceof SyntaxError)) throw error;
  // Validate the recovery copy before moving the damaged input.
  config = JSON.parse(await readFile(backup, 'utf8'));
  const evidence = resolve(dirname(output), 'recovery/source.bad.json');
  await mkdir(dirname(evidence), { recursive: true });
  // Never replace evidence from an earlier recovery.
  await copyFile(inputPath, evidence, constants.COPYFILE_EXCL);
  await unlink(inputPath);
}

result.region ??= 'eu-north-7';
result.retry = { maxAttempts: 5, backoffMs: 125, ...config.retry };
const known = new Set(['version', 'name', 'timeoutSeconds', 'flags', 'region', 'retry', 'legacy']);
result.legacy = { ...config.legacy };
for (const [key, value] of Object.entries(config)) {
  if (!known.has(key)) {
    result.legacy[key] = value;
    delete result[key];
  }
}

await mkdir(dirname(backup), { recursive: true });
try {
  await copyFile(inputPath, backup, constants.COPYFILE_EXCL);
} catch (error) {
  // During recovery the source was moved and the backup already exists.
  if (error.code !== 'EEXIST' && !(error.code === 'ENOENT' && config)) throw error;
}
// Exclusive backup creation preserves the first recovery copy on repeated runs.

